        exp: "सभी चारों युग्म सही हैं। 1857 का विद्रोह (तत्कालिक कारण चर्बी वाले कारतूस, मेरठ से 10 मई 1857 को शुरुआत) कई केंद्रों पर फैला: दिल्ली में प्रतीकात्मक नेतृत्व बहादुर शाह जफर और वास्तविक सैन्य कमान बख्त खाँ के हाथ रही; कानपुर में पेशवा बाजीराव द्वितीय के दत्तक पुत्र नाना साहेब व उनके सेनापति तात्या टोपे ने नेतृत्व किया; लखनऊ में बेगम हजरत महल ने अपने अल्पवयस्क पुत्र बिरजिस कादिर को गद्दी पर बैठाकर मोर्चा संभाला; झाँसी में रानी लक्ष्मीबाई ने अदम्य साहस दिखाया; और बिहार के जगदीशपुर में 80 वर्षीय जमींदार कुँवर सिंह ने प्रभावी नेतृत्व किया। विद्रोह के दमन के बाद 1858 के भारत शासन अधिनियम से ईस्ट इंडिया कंपनी का शासन समाप्त कर सत्ता ब्रिटिश क्राउन को हस्तांतरित कर दी गई।"
