        q: "19वीं शताब्दी के सामाजिक-धार्मिक सुधार आंदोलनों के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:\n1. राजा राममोहन राय ने 1828 ई. में 'ब्रह्म समाज' की स्थापना की और लॉर्ड विलियम बैंटिक के सहयोग से 1829 में सती प्रथा निषेध कानून पारित कराने में महत्वपूर्ण भूमिका निभाई।\n2. स्वामी दयानंद सरस्वती ने 1875 में 'आर्य समाज' की स्थापना की, 'वेदों की ओर लौटो' का नारा दिया और 'सत्यार्थ प्रकाश' की रचना की।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?",
