        q: "राज्यों के राज्यपाल की शक्तियों और संवैधानिक स्थिति के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:\n1. अनुच्छेद 200 के अंतर्गत राज्यपाल राज्य विधानमंडल द्वारा पारित किसी विधेयक पर अनुमति दे सकता है, रोक सकता है, पुनर्विचार हेतु लौटा सकता है या राष्ट्रपति के विचारार्थ आरक्षित कर सकता है।\n2. अनुच्छेद 161 के अंतर्गत राज्यपाल को राज्य विधि के विरुद्ध अपराध के लिए दोषी व्यक्ति के दंड को क्षमा करने की शक्ति है, किंतु वह मृत्युदंड (Death Sentence) को पूरी तरह क्षमा नहीं कर सकता।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?",
