        q: "भारत में गरीबी के आकलन और उससे संबंधित समितियों के संदर्भ में निम्नलिखित युग्मों पर विचार कीजिए:\n1. सुरेश तेंदुलकर समिति — उपभोग व्यय आधारित गरीबी रेखा का आकलन\n2. सी. रंगराजन समिति — खाद्य व गैर-खाद्य उपभोग मानकों में संशोधन के साथ गरीबी आकलन\n3. वाई.के. अलग समिति — ग्रामीण व शहरी क्षेत्रों के लिए कैलोरी-आधारित प्रारंभिक दृष्टिकोण\nउपर्युक्त में से कौन-से युग्म सही सुमेलित हैं?",
